settings.custom_liquid:
{% comment %}
  Countdown Timer Snippet

 Usage: {% render 'countdown-timer' %}

  Default date set to: 02.11.2025 10:00:00
{% endcomment %}

{% unless end_date %}
  {% assign end_date = '2025-11-02T10:00:00' %}
{% endunless %}

{% assign timer_id = 'countdown-timer-' | append: end_date | md5 %}

<div class="countdown-timer" id="{{ timer_id }}">
  <h2 class="countdown-timer__headline">EURE IDEE - UNSER GEMEINSAMES PRODUKT. BALD DA!</h2>
  <div class="countdown-timer__container">
    <div class="countdown-timer__item">
      <span class="countdown-timer__value" data-days>00</span>
      <span class="countdown-timer__label">Tage</span>
    </div>
    <div class="countdown-timer__separator">:</div>
    <div class="countdown-timer__item">
      <span class="countdown-timer__value" data-hours>00</span>
      <span class="countdown-timer__label">Stunden</span>
    </div>
    <div class="countdown-timer__separator">:</div>
    <div class="countdown-timer__item">
      <span class="countdown-timer__value" data-minutes>00</span>
      <span class="countdown-timer__label">Minuten</span>
    </div>
    <div class="countdown-timer__separator">:</div>
    <div class="countdown-timer__item">
      <span class="countdown-timer__value" data-seconds>00</span>
      <span class="countdown-timer__label">Sekunden</span>
    </div>
  </div>
  <div class="countdown-timer__expired" style="display: none;">
    <p>Offer Expired!</p>
  </div>
</div>

<style>
@font-face {
  font-family: 'GT Pressura Bold';
  src: url('https://cdn.shopify.com/s/files/1/0326/4859/3539/files/GT-Pressura-Bold.woff2?v=1754313265') format('woff2');
  font-weight: bold;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: 'GT Pressura Mono';
  src: url('https://cdn.shopify.com/s/files/1/0326/4859/3539/files/GT-Pressura-Mono-Regular.woff2?v=1681482243') format('woff2');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

.countdown-timer {
  font-family: 'GT Pressura Mono', monospace, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
  padding: 20px 20px;
  text-align: center;
  background-color: #f5f5f5;
}

.countdown-timer__headline {
  font-family: 'GT Pressura Bold', sans-serif;
  font-size: 1.5rem;
  font-weight: bold;
  margin: 0 0 20px 0;
  color: #000;
  line-height: 1.2;
}

.countdown-timer__container {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.countdown-timer__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 60px;
}

.countdown-timer__value {
  font-size: 2rem;
  font-weight: bold;
  color: #000;
  line-height: 1;
}

.countdown-timer__label {
  font-size: 0.75rem;
  color: #666;
  margin-top: 4px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.countdown-timer__separator {
  font-size: 1.5rem;
  font-weight: bold;
  color: #000;
  margin: 0 3px;
}

.countdown-timer__expired {
  font-size: 1.25rem;
  font-weight: bold;
  color: #e74c3c;
}

@media (max-width: 768px) {
  .countdown-timer {
    padding: 20px 15px;
  }

  .countdown-timer__headline {
    font-size: 1.125rem;
    margin-bottom: 15px;
  }

  .countdown-timer__value {
    font-size: 1.5rem;
  }

  .countdown-timer__item {
    min-width: 50px;
  }

  .countdown-timer__separator {
    font-size: 1.2rem;
    margin: 0 2px;
  }

  .countdown-timer__label {
    font-size: 0.625rem;
    margin-top: 3px;
  }

  .countdown-timer__container {
    gap: 5px;
  }
}
</style>

<script>
(function() {
  const timerId = '{{ timer_id }}';
  const endDate = new Date('{{ end_date }}').getTime();
  const timerElement = document.getElementById(timerId);

  if (!timerElement) return;

  const daysEl = timerElement.querySelector('[data-days]');
  const hoursEl = timerElement.querySelector('[data-hours]');
  const minutesEl = timerElement.querySelector('[data-minutes]');
  const secondsEl = timerElement.querySelector('[data-seconds]');
  const containerEl = timerElement.querySelector('.countdown-timer__container');
  const expiredEl = timerElement.querySelector('.countdown-timer__expired');

  function updateCountdown() {
    const now = new Date().getTime();
    const distance = endDate - now;

    if (distance < 0) {
      clearInterval(interval);
      containerEl.style.display = 'none';
      expiredEl.style.display = 'block';
      return;
    }

    const days = Math.floor(distance / (1000 * 60 * 60 * 24));
    const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((distance % (1000 * 60)) / 1000);

    daysEl.textContent = String(days).padStart(2, '0');
    hoursEl.textContent = String(hours).padStart(2, '0');
    minutesEl.textContent = String(minutes).padStart(2, '0');
    secondsEl.textContent = String(seconds).padStart(2, '0');
  }

  updateCountdown();
  const interval = setInterval(updateCountdown, 1000);
})();
</script>

